import unittest
import secrets
import random
import string

from TorchModelCompress import pytorchModel


def nothing(fromCpp):
    return 0


def rand_key(p):
    key1 = ""
    for i in range(p):
        temp = str(secrets.randbits(1))
        key1 += temp

    return key1


testString = b"This is a Test"
padString = b"aaa"


class TestStringMethods(unittest.TestCase):

    def test_MutiblePytorchModel(self):
        a = pytorchModel("DEv1.pt")
        b = pytorchModel("DEv1.pt")
        c = pytorchModel("Num.pt")

    def test_getCharList(self):
        a = pytorchModel("DEv0.pt")
        self.assertEqual(a.getCharList(), '\n !"#%&\'()*+,-./0123456789:;=?ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz|§«°²»ÄÉÖ×Üßàáâãäçèéíñóôöøúüýāćčěıłōřšū–‘’‚“„†…')

    def test_loadBlacklist1(self):
        a = pytorchModel("DEv1.pt")
        with self.assertRaises(RuntimeError):
            a.loadBlacklist("notHere", True, True)

    def test_loadBlacklist2(self):
        a = pytorchModel("DEv1.pt")
        a.loadBlacklist("blacklist.txt", True, True)
        aR1 = a.getInitState()
        aR1.initRangeCoding(63)
        temp = aR1.decodeToBinaryRangeCoding(testString + padString, 1, nothing, True, 1, 63, 64)

    def test_loadBlacklist3(self):
        a = pytorchModel("DEv1.pt")
        a.loadBlacklistLine("\n", True)
        aR1 = a.getInitState()
        aR1.initRangeCoding(63)
        temp = aR1.decodeToBinaryRangeCoding(testString + padString, 1, nothing, True, 1, 63, 64)

    def test_decAndBack(self):
        a = pytorchModel("DEv1.pt")
        aR1 = a.getInitState()
        aR1.initRangeCoding(63)
        aR2 = a.getInitState()
        aR2.initRangeCoding(63)
        temp = aR2.decodeToBinaryRangeCoding(testString + padString, 1, nothing, True, 1, 63, 64)[0]
        self.assertEqual(temp.translate(str.maketrans('', '', '01')), "")
        self.assertNotEqual(temp, "")
        output = aR1.decodeFromBinaryRangeCoding(temp + rand_key(100), len(temp), 1, nothing, True, 1, 63, 64)[0]
        self.assertEqual(output[:len(testString)], testString)

    def test_clone_decAndBack(self):
        a = pytorchModel("DEv1.pt")
        b = a.clone()
        aR1 = a.getInitState()
        aR1.initRangeCoding(63)
        aR2 = b.getInitState()
        aR2.initRangeCoding(63)
        temp = aR2.decodeToBinaryRangeCoding(testString + padString, 1, nothing, True, 1, 63, 64)[0]
        self.assertEqual(temp.translate(str.maketrans('', '', '01')), "")
        self.assertNotEqual(temp, "")
        output = aR1.decodeFromBinaryRangeCoding(temp + rand_key(100), len(temp), 1, nothing, True, 1, 63, 64)[0]
        self.assertEqual(output[:len(testString)], testString)

