    def test_Clone(self):
        a = pytorchModel("DEv1.pt")
        trand = rand_key(500)
        aR1 = a.getInitState()
        aR1.initRangeCoding(63)
        aR2 = aR1.cloneDecState()
        temp = aR1.decodeToBinaryRangeCoding(testString + padString, 1, nothing, True, 1, 63, 64)[0]
        aR1.resetDecState()
        aR1.initRangeCoding(63)
        sink = aR1.decodeFromBinaryRangeCoding(temp + trand, len(temp) + 100, 1, nothing, False, 1, 63, 64)[0]
        aR3 = aR1.cloneDecState()
        self.assertEqual(temp.translate(str.maketrans('', '', '01')), "")
        self.assertNotEqual(temp, "")
        output1 = aR2.decodeFromBinaryRangeCoding(temp + trand, len(temp) + 100, 1, nothing, False, 1, 63, 64)[0]
        self.assertEqual(output1[:len(testString)], testString)
        output2 = aR2.decodeFromBinaryRangeCoding(temp + trand, len(temp) + 100, 1, nothing, False, 1, 63, 64)[0]
        self.assertNotEqual(output2[:len(testString)], testString)
        output3 = aR3.decodeFromBinaryRangeCoding(temp + trand, len(temp) + 100, 1, nothing, False, 1, 63, 64)[0]
        self.assertNotEqual(output3[:len(testString)], testString)
        self.assertEqual(output3[:len(testString)], output2[:len(testString)])

    def test_bruteforce(self):
        a = pytorchModel("DEv1.pt")
        for i in range(200):
            minUserfull = secrets.randbelow(500) + 32
            normal = minUserfull + secrets.randbelow(500)
            startbuff = minUserfull + secrets.randbelow(500)
            corfactor = 0.5 + random.random()
            breakIn = (secrets.randbelow(2) == 1)

            size = secrets.randbelow(100)

            toDec = rand_key(size)
            randPad = rand_key(5000)
            aR1 = a.getInitState()
            aR1.initRangeCoding(startbuff)
            aR2 = a.getInitState()
            aR2.initRangeCoding(startbuff)
            output = aR1.decodeFromBinaryRangeCoding(toDec + randPad, len(toDec), 1, nothing, True, corfactor, minUserfull, normal)[0]
            sizeBreak = 0
            if (breakIn):
                sizeBreak = secrets.randbelow(len(output))
                part1 =           aR2.decodeToBinaryRangeCoding(output[:sizeBreak]           , 1, nothing, False, corfactor, minUserfull, normal)
                temp = part1[0] + aR2.decodeToBinaryRangeCoding(output[sizeBreak - part1[1]:], 1, nothing, True,  corfactor, minUserfull, normal)[0]
            else:
                temp =            aR2.decodeToBinaryRangeCoding(output                       , 1, nothing, True,  corfactor, minUserfull, normal)[0]
            self.assertEqual(temp[:len(toDec)], toDec, "minUserfull: " + str(minUserfull) + " normal: " + str(normal) + " startbuff: " + str(startbuff) + " corfactor: " + str(corfactor) + " breakIn: " + str(breakIn) + " size: " + str(size) + " sizeBreak: " + str(sizeBreak) + " toDec: " + str(toDec) + " Pad: " + str(randPad))

    def test_bruteforce_token(self):
        a = pytorchModel("DEv1.pt")
        for i in range(200):
            minUserfull = secrets.randbelow(500) + 32
            normal = minUserfull + secrets.randbelow(500)
            startbuff = minUserfull + secrets.randbelow(500)
            corfactor = 0.5 + random.random()

            size = secrets.randbelow(100)

            randToEncode = ''.join(random.choices(string.printable + "äü¶☼", k=size)).encode()
            aR2 = a.getInitState()
            aR2.initRangeCoding(startbuff)
            temp = aR2.decodeToBinaryRangeCoding(randToEncode, 1, nothing, True,  corfactor, minUserfull, normal)[0]

    def test_noInit(self):
        a = pytorchModel("DEv1.pt")
        a.loadBlacklist("blacklist.txt", True, True)
        aR1 = a.getInitState()
        with self.assertRaises(RuntimeError):
            temp = aR1.decodeToBinaryRangeCoding(testString + padString, 1, nothing, True, 1, 63, 64)
        aR2 = a.getInitState()
        temp = "101001"
        with self.assertRaises(RuntimeError):
            aR2.decodeFromBinaryRangeCoding(temp + rand_key(100), len(temp), 1, nothing, True, 1, 63, 64)[0]

    def test_lowToken(self):
        a = pytorchModel("DEv1.pt")

        minUserfull = 272
        normal = 726
        startbuff = 334
        corfactor = 1
        size = 4
        toDec = "0000"
        randPad = ""

        aR1 = a.getInitState()
        aR1.initRangeCoding(startbuff)
        aR2 = a.getInitState()
        aR2.initRangeCoding(startbuff)
        output = aR1.decodeFromBinaryRangeCoding(toDec + randPad, len(toDec), 1, nothing, True, corfactor, minUserfull, normal)[0]
        temp = aR2.decodeToBinaryRangeCoding(output, 1, nothing, True,  corfactor, minUserfull, normal)[0]
        self.assertEqual(temp[:len(toDec)], toDec, "minUserfull: " + str(minUserfull) + " normal: " + str(normal) + " startbuff: " + str(startbuff) + " corfactor: " + str(corfactor) + " breakIn: " + str(breakIn) + " size: " + str(size) + " Pad: " + str(randPad))

    def test_knownBad1(self):
        a = pytorchModel("DEv1.pt")

        minUserfull = 50
        normal = 162
        startbuff = 180
        corfactor = 0.893690466367339
        breakIn = True
        toDec = "01110111"
        randPad = ""

        aR1 = a.getInitState()
        aR1.initRangeCoding(startbuff)
        aR2 = a.getInitState()
        aR2.initRangeCoding(startbuff)
        output = aR1.decodeFromBinaryRangeCoding(toDec + randPad, len(toDec), 1, nothing, True, corfactor, minUserfull, normal)[0]
        size = 7
        r1 =   aR2.decodeToBinaryRangeCoding(output[:size]        , 1, nothing, False, corfactor, minUserfull, normal)
        rest = aR2.decodeToBinaryRangeCoding(output[size - r1[1]:], 1, nothing, True,  corfactor, minUserfull, normal)
        temp = r1[0] + rest[0]

        self.assertEqual(temp[:len(toDec)], toDec, "minUserfull: " + str(minUserfull) + " normal: " + str(normal) + " startbuff: " + str(startbuff) + " corfactor: " + str(corfactor) + " breakIn: " + str(breakIn) + " size: " + str(size) + " Pad: " + str(randPad))


